/**
 * ============================================================================
 * CRW+ FITNESS - CENTRAL TRANSLATIONS & INTERNATIONALIZATION (i18n)
 * ============================================================================
 *
 * JAK DODAĆ NOWY JĘZYK / HOW TO ADD A NEW LANGUAGE:
 * ----------------------------------------------------------------------------
 * 1. Dodaj kod języka i jego czytelną nazwę do `SUPPORTED_LANGUAGES`:
 *    np. es: 'Español', de: 'Deutsch', uk: 'Українська', fr: 'Français'.
 *
 * 2. W obiekcie `translations` poniżej, dodaj nowy klucz dla swojego języka:
 *    es: {
 *      // Skopiuj strukturę z 'en' i przetłumacz teksty na język docelowy.
 *      // Każdy nieprzetłumaczony klucz automatycznie użyje wersji angielskiej.
 *    }
 *
 * 3. Gotowe! Język automatycznie:
 *    - Pokaże się jako dostępny w Onboarding i Ustawieniach profilu,
 *    - Trafi na szczyt listy wyboru języków bez oznaczenia "(SOON)",
 *    - Będzie w pełni obsługiwany przez funkcję `t()` i hook `useTranslation()`.
 * ============================================================================
 */

