export type AppTranslations = typeof en;
// Non-English locales may omit keys; t() falls back to English for anything missing, so
// they are typed loosely rather than forced to carry every key.
type DeepPartial<T> = { [K in keyof T]?: T[K] extends object ? DeepPartial<T[K]> : T[K] };

