export const translations: Record<string, AppTranslations> = {
  en,
  pl,
  ar,
  es,
  de,
  fr,
  it,
  pt,
  uk,
  ru,
  tr,
  ja,
  ko,
  zh,
  nl,
  sv,
  no,
  da,
  fi,
  cs,
  sk,
  hu,
  el,
  ro,
};

const STORAGE_KEY = 'crw_app_language';

function getInitialLanguage(): string {
  try {
    if (typeof localStorage !== 'undefined') {
      const saved = localStorage.getItem(STORAGE_KEY);
      if (saved && typeof saved === 'string') return saved;
    }
  } catch {}
  return 'en';
}

let activeLanguage = getInitialLanguage();
const listeners = new Set<(lang: string) => void>();

export async function loadLanguage(): Promise<string> {
  try {
    const saved = await AsyncStorage.getItem(STORAGE_KEY);
    if (saved && saved !== activeLanguage) {
      activeLanguage = saved;
      listeners.forEach((cb) => cb(saved));
    }
  } catch {}
  return activeLanguage;
}

/**
 * Returns translated string for a given nested dot path (e.g. 'nav.discover' or 'auth.nameLabel').
 * Replaces parameters with {param} or {{param}}.
 * Falls back to English if the key is missing in the chosen language or if the language is not translated.
 */
export function t(
  path: string,
  params: Record<string, string | number> = {},
  lang: string = activeLanguage,
): string {
  const dict = translations[lang] || translations.en;
  const fallbackDict = translations.en;

  const resolve = (obj: any, p: string) =>
    p.split('.').reduce((acc, part) => (acc && acc[part] !== undefined ? acc[part] : null), obj);

  let val = resolve(dict, path);
  if (val == null) val = resolve(fallbackDict, path);
  if (val == null) return path;

  let text = String(val);
  for (const [k, v] of Object.entries(params)) {
    text = text.replace(new RegExp(`\\{\\{?\\s*${k}\\s*\\}?}`, 'g'), String(v));
  }
  return text;
}

export function getGlobalLanguage(): string {
  return activeLanguage;
}

/** Sets the global active language and persists to storage */
export function setGlobalLanguage(lang: string) {
  if (!lang || activeLanguage === lang) return;
  activeLanguage = lang;
  try {
    if (typeof localStorage !== 'undefined') {
      localStorage.setItem(STORAGE_KEY, lang);
    }
  } catch {}
  void AsyncStorage.setItem(STORAGE_KEY, lang).catch(() => {});
  listeners.forEach((cb) => cb(lang));
}

/**
 * React hook for using translations in components.
 */
export function useTranslation() {
  const [lang, setLang] = useState(activeLanguage);

  useEffect(() => {
    if (activeLanguage !== lang) {
      setLang(activeLanguage);
    }
    const cb = (newLang: string) => setLang(newLang);
    listeners.add(cb);
    return () => {
      listeners.delete(cb);
    };
  }, [lang]);

  const changeLanguage = useCallback((newLang: string) => {
    setGlobalLanguage(newLang);
  }, []);

  const translate = useCallback(
    (path: string, params?: Record<string, string | number>) => {
      return t(path, params, lang);
    },
    [lang],
  );

  return {
    t: translate,
    language: lang,
    setLanguage: changeLanguage,
    availableLanguages: LANGUAGES,
    isTranslated: TRANSLATED_LANGUAGES.has(lang),
  };
}
